func newPage() unsafe.Pointer { return unsafe.Pointer(new(documentcontent.Page)) }

func newNPage(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]documentcontent.Page, n)))
}

func ptrPage(p unsafe.Pointer, c int32) any {
	r := (*documentcontent.Page)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.DocumentContentID))
	case 2:
		return (*string)(unsafe.Pointer(&r.DocumentID))
	case 3:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 4:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 5:
		return (*int64)(unsafe.Pointer(&r.PageNumber))
	case 6:
		return (*string)(unsafe.Pointer(&r.SourceKind))
	case 7:
		return &r.ExtractedText
	case 8:
		return &r.Markdown
	case 9:
		return &r.OCRConfidence
	case 10:
		return &r.PreprocessingApplied
	case 11:
		return (*int64)(unsafe.Pointer(&r.Width))
	case 12:
		return (*int64)(unsafe.Pointer(&r.Height))
	case 13:
		return &r.Metadata
	case 14:
		return &r.Version
	case 15:
		return &r.CreatedAt
	case 16:
		return &r.UpdatedAt
	}
	return nil
}

func valuePage(p unsafe.Pointer, c int32) any {
	r := (*documentcontent.Page)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.DocumentContentID)
	case 2:
		return string(r.DocumentID)
	case 3:
		return string(r.OrganizationID)
	case 4:
		return string(r.BusinessUnitID)
	case 5:
		return int64(r.PageNumber)
	case 6:
		return string(r.SourceKind)
	case 7:
		if r.ExtractedText == "" {
			return nil
		}
		return r.ExtractedText
	case 8:
		if r.Markdown == "" {
			return nil
		}
		return r.Markdown
	case 9:
		return r.OCRConfidence
	case 10:
		return r.PreprocessingApplied
	case 11:
		return int64(r.Width)
	case 12:
		return int64(r.Height)
	case 13:
		if r.Metadata == nil {
			return keel.EmptyJSONObject
		}
		return r.Metadata
	case 14:
		return r.Version
	case 15:
		return r.CreatedAt
	case 16:
		return r.UpdatedAt
	}
	return nil
}

